-- Extend OTA scope to every supported accommodation profile type.
-- Restaurant-only, clinic, retail and unrelated business tenants remain excluded.

drop policy if exists ota_property_scope_guard on public.ota_channels;
create policy ota_property_scope_guard on public.ota_channels as restrictive for all to public
using (exists (select 1 from public.restaurants r where r.id=ota_channels.restaurant_id and (
  r.business_type in ('hotel_resort','hotel_restaurant','camping') or
  lower(coalesce(r.hospitality_type,'')) in ('hotel','camp','camping','homestay','guest_house','cottage','resort','villa','hostel','farm_stay','lodge','motel','glamping') or
  coalesce(r.hospitality_types,array[]::text[]) && array['hotel','camp','camping','homestay','guest_house','cottage','resort','villa','hostel','farm_stay','lodge','motel','glamping']::text[]
)))
with check (exists (select 1 from public.restaurants r where r.id=ota_channels.restaurant_id and (
  r.business_type in ('hotel_resort','hotel_restaurant','camping') or lower(coalesce(r.hospitality_type,'')) in ('hotel','camp','camping','homestay','guest_house','cottage','resort','villa','hostel','farm_stay','lodge','motel','glamping') or coalesce(r.hospitality_types,array[]::text[]) && array['hotel','camp','camping','homestay','guest_house','cottage','resort','villa','hostel','farm_stay','lodge','motel','glamping']::text[]
)));

